import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, SessionRateLimit } from 'claude-code'

import type {
  UsageContext,
  UsageFallback,
  UsageLimits,
  UsageTokens,
  UsageWindow,
} from '../types'

const limitsAtom = atom({ plugin: 'usage-band', key: 'limits' } as const, null)
const costAtom = atom({ plugin: 'usage-band', key: 'cost' } as const, null)
const contextAtom = atom({ plugin: 'usage-band', key: 'context' } as const, null)
const tokensAtom = atom({ plugin: 'usage-band', key: 'tokens' } as const, null)
const fallbackAtom = atom({ plugin: 'usage-band', key: 'fallback' } as const, {
  uncachedInput: 0,
  cacheWrite: 0,
  output: 0,
  cacheRead: 0,
  turns: 0,
})
const hiddenAtom = atom({ plugin: 'usage-band', key: 'isHidden' } as const, false)
const nowAtom = atom({ plugin: 'usage-band', key: 'now' } as const, 0)

const FIVE_HOURS = 5 * 3600 * 1000
const SEVEN_DAYS = 7 * 24 * 3600 * 1000
const NODES = ['node', '/usr/local/bin/node', '/opt/homebrew/bin/node']

type Kind = 'h5' | 'd7' | 'in' | 'out' | 'cache' | 'cost'

type Model = {
  limits: UsageLimits | null
  cost: number | null
  context: UsageContext | null
  tokens: UsageTokens | null
  fallback: UsageFallback
  now: number
}

// ---------- formatting ----------

export const fmtTokens = (n: number): string => {
  if (n < 1000) return String(Math.round(n))
  if (n < 1_000_000) return `${(n / 1000).toFixed(1)}k`
  return `${(n / 1_000_000).toFixed(2)}M`
}

export const fmtLeft = (ms: number): string => {
  const minutes = Math.max(0, Math.floor(ms / 60000))
  const d = Math.floor(minutes / 1440)
  const h = Math.floor((minutes % 1440) / 60)
  const m = minutes % 60
  if (d > 0) return `${d}d ${h}h`
  if (h > 0) return `${h}h ${m}m`
  return `${m}m`
}

const fmtUsd = (usd: number): string => `$${usd.toFixed(2)}`

const fmtInt = (n: number): string => Math.round(n).toLocaleString('en-US')

const level = (pct: number): 'ok' | 'warn' | 'bad' =>
  pct >= 90 ? 'bad' : pct >= 70 ? 'warn' : 'ok'

const elapsedFraction = (w: UsageWindow, length: number, now: number): number | null => {
  if (w.resetsAt === null) return null
  const left = Math.min(length, Math.max(0, w.resetsAt - now))
  return 1 - left / length
}

const esc = (s: string): string =>
  s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')

// ---------- SVG pills (desktop) ----------

const FONT = 12
const CHAR = 7.3
const H = 22
const PAD = 8

const STYLE = `
.bg{rx:11}
.h5 .bg{fill:#d3f1ea}.h5{color:#0d4a40}
.d7 .bg{fill:#e9e1fb}.d7{color:#3b2775}
.in .bg{fill:#fbe1dc}.in{color:#7a2317}
.out .bg{fill:#dcf2db}.out{color:#1e5821}
.cache .bg{fill:#dce8fb}.cache{color:#1a427f}
.cost .bg{fill:#fbefc9}.cost{color:#664a00}
text{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:${FONT}px;fill:currentColor}
.b{font-weight:700}
.ic{fill:none;stroke:currentColor;stroke-width:1.3;stroke-linecap:round;stroke-linejoin:round}
.trk{fill:currentColor;opacity:.18}
.sep{stroke:currentColor;opacity:.35}
.tl{stroke:currentColor;stroke-width:1.4}
.ok{fill:#2f9e5c}.warn{fill:#d39e00}.bad{fill:#d64545}
@media (prefers-color-scheme: dark){
.h5 .bg{fill:#103a34}.h5{color:#b5eee2}
.d7 .bg{fill:#2a2146}.d7{color:#d8cbff}
.in .bg{fill:#45201a}.in{color:#ffc8bd}
.out .bg{fill:#1c3a1e}.out{color:#c1eec2}
.cache .bg{fill:#19294a}.cache{color:#c3daff}
.cost .bg{fill:#3d3112}.cost{color:#f4da8c}
.ok{fill:#4cc27a}.warn{fill:#f0c419}.bad{fill:#ff6b6b}
}`

const ICONS: Record<string, string> = {
  clock: '<circle class="ic" cx="6" cy="6" r="5"/><path class="ic" d="M6 3v3l2 1.5"/>',
  calendar:
    '<rect class="ic" x="1" y="2" width="10" height="9" rx="1.5"/><path class="ic" d="M1 5h10M4 0.8v2.4M8 0.8v2.4"/>',
  hourglass: '<path class="ic" d="M3 1h6M3 11h6M3.5 1c0 3 5 3 5 5s-5 2-5 5M8.5 1c0 3-5 3-5 5s5 2 5 5"/>',
  up: '<path class="ic" d="M6 11V1.5M2 5.5l4-4 4 4"/>',
  down: '<path class="ic" d="M6 1v9.5M2 6.5l4 4 4-4"/>',
  layers: '<path class="ic" d="M6 1l5 2.6-5 2.6-5-2.6z"/><path class="ic" d="M1 6.3l5 2.6 5-2.6M1 8.8l5 2.6 5-2.6"/>',
  dollar:
    '<path class="ic" d="M6 0.5v11M8.6 3.2C8.2 2.3 7.2 1.9 6 1.9c-1.5 0-2.6.8-2.6 1.9 0 2.6 5.3 1.4 5.3 4.2 0 1.1-1.1 2-2.7 2-1.3 0-2.4-.5-2.8-1.5"/>',
}

type Part =
  | { t: 'icon'; name: string }
  | { t: 'text'; s: string; bold?: boolean }
  | { t: 'bar'; pct: number; elapsed: number | null }
  | { t: 'sep' }

const partWidth = (p: Part): number =>
  p.t === 'icon' ? 12 : p.t === 'text' ? p.s.length * CHAR : p.t === 'bar' ? 44 : 9

const pill = (kind: Kind, parts: Part[], tip: string): { source: string; width: number } => {
  const GAP = 5
  const inner = parts.reduce((sum, p) => sum + partWidth(p), 0) + GAP * (parts.length - 1)
  const width = Math.ceil(inner + PAD * 2)
  let x = PAD
  const body: string[] = []
  for (const p of parts) {
    if (p.t === 'icon') {
      body.push(`<g transform="translate(${x.toFixed(1)} 5)">${ICONS[p.name] ?? ''}</g>`)
    } else if (p.t === 'text') {
      body.push(
        `<text x="${x.toFixed(1)}" y="15"${p.bold ? ' class="b"' : ''}>${esc(p.s)}</text>`,
      )
    } else if (p.t === 'bar') {
      const w = 44
      const fill = (Math.min(100, Math.max(0, p.pct)) / 100) * w
      body.push(`<rect class="trk" x="${x.toFixed(1)}" y="8.5" width="${w}" height="5" rx="2.5"/>`)
      if (fill > 0) {
        body.push(
          `<rect class="${level(p.pct)}" x="${x.toFixed(1)}" y="8.5" width="${Math.max(2.5, fill).toFixed(1)}" height="5" rx="2.5"/>`,
        )
      }
      if (p.elapsed !== null) {
        const tx = x + Math.min(1, Math.max(0, p.elapsed)) * w
        body.push(`<line class="tl" x1="${tx.toFixed(1)}" y1="4" x2="${tx.toFixed(1)}" y2="16"/>`)
      }
    } else {
      const sx = x + 4.5
      body.push(`<line class="sep" x1="${sx.toFixed(1)}" y1="6" x2="${sx.toFixed(1)}" y2="16"/>`)
    }
    x += partWidth(p) + GAP
  }
  const source =
    `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${H}" viewBox="0 0 ${width} ${H}">` +
    `<style>${STYLE}</style>` +
    `<g class="${kind}"><title>${esc(tip)}</title>` +
    `<rect class="bg" x="0" y="0" width="${width}" height="${H}" rx="11"/>` +
    body.join('') +
    '</g></svg>'
  return { source, width }
}

// ---------- pill model (shared by both surfaces) ----------

type PillSpec = {
  kind: Kind
  group: 0 | 1 | 2
  parts: Part[]
  tip: string
  alt: string
}

const windowSpec = (
  kind: 'h5' | 'd7',
  w: UsageWindow,
  now: number,
): PillSpec => {
  const isFive = kind === 'h5'
  const length = isFive ? FIVE_HOURS : SEVEN_DAYS
  const label = isFive ? '5h' : '7d'
  const elapsed = elapsedFraction(w, length, now)
  const left = w.resetsAt === null ? null : fmtLeft(w.resetsAt - now)
  const pct = `${Math.round(w.percentUsed)}%`
  const parts: Part[] = [
    { t: 'icon', name: isFive ? 'clock' : 'calendar' },
    { t: 'text', s: label },
    { t: 'bar', pct: w.percentUsed, elapsed },
    { t: 'text', s: pct, bold: true },
  ]
  if (left !== null) parts.push({ t: 'sep' }, { t: 'icon', name: 'hourglass' }, { t: 'text', s: left })
  const resetAt = w.resetsAt === null ? 'unknown' : new Date(w.resetsAt).toLocaleString()
  const tip = [
    `${isFive ? '5-hour' : '7-day'} limit: ${w.percentUsed}% used`,
    `Resets in ${left ?? '?'} (${resetAt})`,
    elapsed === null ? 'Window elapsed: ?' : `Window elapsed: ${Math.round(elapsed * 100)}%`,
  ].join('\n')
  return { kind, group: 0, parts, tip, alt: `${label} ${pct}${left ? `, resets in ${left}` : ''}` }
}

const specs = (m: Model): PillSpec[] => {
  const out: PillSpec[] = []
  if (m.limits?.fiveHour) out.push(windowSpec('h5', m.limits.fiveHour, m.now))
  if (m.limits?.sevenDay) out.push(windowSpec('d7', m.limits.sevenDay, m.now))

  const t: UsageTokens | null =
    m.tokens ??
    (m.fallback.turns > 0
      ? {
          uncachedInput: m.fallback.uncachedInput,
          cacheWrite: m.fallback.cacheWrite,
          output: m.fallback.output,
          cacheRead: m.fallback.cacheRead,
          requests: m.fallback.turns,
          isApprox: true,
          dump: '',
          subagentFiles: 0,
        }
      : null)
  if (t && t.requests > 0) {
    const pre = t.isApprox ? '~' : ''
    const ctx = m.context
    const ctxLine = ctx
      ? `Context: ${ctx.percent === null ? '?' : `${Math.round(ctx.percent)}%`} of ${fmtTokens(ctx.window)}${ctx.tokens === null ? '' : ` (${fmtInt(ctx.tokens)} tokens)`}`
      : 'Context: unknown'
    const source = t.isApprox
      ? `Source: turn.complete totals (${t.requests} turns, approximate)`
      : `Dump: ${t.dump}${t.subagentFiles ? ` + ${t.subagentFiles} subagent file(s)` : ''}`
    const reqLine = t.isApprox ? `Turns: ${t.requests}` : `Requests: ${t.requests}`
    const input = t.uncachedInput + t.cacheWrite
    out.push({
      kind: 'in',
      group: 1,
      parts: [{ t: 'icon', name: 'up' }, { t: 'text', s: pre + fmtTokens(input) }],
      tip: [
        `Input tokens: ${fmtInt(input)}`,
        `  uncached ${fmtInt(t.uncachedInput)} + cache writes ${fmtInt(t.cacheWrite)}`,
        reqLine,
        ctxLine,
        source,
      ].join('\n'),
      alt: `input ${pre}${fmtTokens(input)}`,
    })
    out.push({
      kind: 'out',
      group: 1,
      parts: [{ t: 'icon', name: 'down' }, { t: 'text', s: pre + fmtTokens(t.output) }],
      tip: [`Output tokens: ${fmtInt(t.output)}`, reqLine, ctxLine, source].join('\n'),
      alt: `output ${pre}${fmtTokens(t.output)}`,
    })
    out.push({
      kind: 'cache',
      group: 1,
      parts: [{ t: 'icon', name: 'layers' }, { t: 'text', s: pre + fmtTokens(t.cacheRead) }],
      tip: [`Cache read tokens: ${fmtInt(t.cacheRead)}`, reqLine, ctxLine, source].join('\n'),
      alt: `cache read ${pre}${fmtTokens(t.cacheRead)}`,
    })
  }
  if (m.cost !== null && out.length > 0) {
    out.push({
      kind: 'cost',
      group: 2,
      parts: [{ t: 'icon', name: 'dollar' }, { t: 'text', s: m.cost.toFixed(2) }],
      tip: `Session cost: $${m.cost.toFixed(4)}\nat API list price (as /cost totals it)`,
      alt: `cost ${fmtUsd(m.cost)}`,
    })
  }
  return out
}

export const renderSvgPills = (m: Model) =>
  specs(m).map(s => ({ ...s, ...pill(s.kind, s.parts, s.tip) }))

// ---------- terminal ----------

const TERM_COLOR: Record<Kind, string> = {
  h5: '#2bb3a0',
  d7: '#9b7be0',
  in: '#e0705f',
  out: '#4caf50',
  cache: '#4a8fe0',
  cost: '#d4a72c',
}
const LEVEL_COLOR = { ok: '#4caf50', warn: '#e0b000', bad: '#e05050' }
const TERM_ICON: Record<string, string> = {
  clock: '◷',
  calendar: '▦',
  hourglass: '⧗',
  up: '↑',
  down: '↓',
  layers: '≋',
  dollar: '$',
}

const termBar = (pct: number, elapsed: number | null): { fill: string; mark: number; rest: string } => {
  const cells = 10
  const filled = Math.round((Math.min(100, Math.max(0, pct)) / 100) * cells)
  const mark = elapsed === null ? -1 : Math.min(cells - 1, Math.round(elapsed * cells))
  return { fill: '█'.repeat(filled), mark, rest: '░'.repeat(cells - filled) }
}

// ---------- data ----------

const toWindow = (r: SessionRateLimit | undefined): UsageWindow | null => {
  if (!r) return null
  const at = r.resetsAt ? Date.parse(r.resetsAt) : NaN
  return { percentUsed: r.percentUsed, resetsAt: Number.isFinite(at) ? at : null }
}

const toLimits = (list: readonly SessionRateLimit[]): UsageLimits | null => {
  const fiveHour = toWindow(list.find(r => r.kind === 'five_hour'))
  const sevenDay = toWindow(list.find(r => r.kind === 'seven_day'))
  return fiveHour || sevenDay ? { fiveHour, sevenDay } : null
}

type ScriptOut = {
  uncachedInput: number
  cacheWrite: number
  output: number
  cacheRead: number
  requests: number
  mainPath: string
  subDir: string
  subagentFiles: number
  sig: string
}

let nodePath: string | null = null
let lastSig: string | null = null
let lastPaths: { mainPath: string; subDir: string } | null = null
let busy = false

const currentSig = async ($: EngineInterface): Promise<string | null> => {
  if (!lastPaths) return null
  try {
    const main = await $.fs.stat(lastPaths.mainPath)
    const parts = [`main:${main.size}:${Math.trunc(main.mtimeMs)}`]
    if (await $.fs.exists(lastPaths.subDir)) {
      const files = (await $.fs.list(lastPaths.subDir))
        .filter(f => f.kind === 'file' && f.name.endsWith('.jsonl'))
        .sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0))
      for (const f of files) parts.push(`${f.name}:${f.size}:${Math.trunc(f.mtimeMs)}`)
    }
    return parts.join('|')
  } catch {
    return null
  }
}

const runScript = async ($: EngineInterface, id: string): Promise<ScriptOut | null> => {
  const script = `${$.plugin.root}/scripts/tokens.mjs`
  const candidates = nodePath ? [nodePath] : NODES
  for (const node of candidates) {
    try {
      const ran = await $.process.run([node, script, id], { timeoutMs: 20000 })
      if (ran.exitCode !== 0) return null
      nodePath = node
      return JSON.parse(ran.stdout.trim()) as ScriptOut
    } catch {
      continue
    }
  }
  return null
}

const refreshTokens = async ($: EngineInterface, force = false): Promise<void> => {
  if (busy) return
  busy = true
  try {
    if (!force && lastSig !== null && (await currentSig($)) === lastSig) return
    const id = await $.session.id()
    const out = await runScript($, id)
    if (!out) {
      lastSig = null
      await update($, tokensAtom, () => null)
      return
    }
    lastSig = out.sig
    lastPaths = { mainPath: out.mainPath, subDir: out.subDir }
    const tokens: UsageTokens = {
      uncachedInput: out.uncachedInput,
      cacheWrite: out.cacheWrite,
      output: out.output,
      cacheRead: out.cacheRead,
      requests: out.requests,
      isApprox: false,
      dump: out.mainPath.split('/').pop() ?? out.mainPath,
      subagentFiles: out.subagentFiles,
    }
    await update($, tokensAtom, () => tokens)
  } finally {
    busy = false
  }
}

const refreshUsage = async ($: EngineInterface): Promise<void> => {
  const u = await $.session.usage()
  await applyUsage($, u.rateLimits, u.cost?.usd ?? null, u.context)
}

const applyUsage = async (
  $: EngineInterface,
  rateLimits: readonly SessionRateLimit[],
  usd: number | null,
  ctx: { tokens?: number; window: number; percent?: number },
): Promise<void> => {
  const limits = toLimits(rateLimits)
  if (limits) await update($, limitsAtom, () => limits)
  await update($, costAtom, () => usd)
  const context: UsageContext = {
    tokens: ctx.tokens ?? null,
    window: ctx.window,
    percent: ctx.percent ?? null,
  }
  await update($, contextAtom, () => context)
}

const refreshAll = async ($: EngineInterface, force = false): Promise<void> => {
  const now = await $.clock.now()
  await update($, nowAtom, () => now)
  await refreshUsage($)
  await refreshTokens($, force)
}

const readModel = async ($: EngineInterface): Promise<Model> => ({
  limits: await read($, limitsAtom),
  cost: await read($, costAtom),
  context: await read($, contextAtom),
  tokens: await read($, tokensAtom),
  fallback: await read($, fallbackAtom),
  now: (await read($, nowAtom)) || (await $.clock.now()),
})

const summary = (m: Model): string => {
  const parts: string[] = []
  for (const s of specs(m)) {
    const text = s.parts
      .filter((p): p is Extract<Part, { t: 'text' }> => p.t === 'text')
      .map(p => p.s)
    if (s.kind === 'h5' || s.kind === 'd7') {
      parts.push(`${text[0]} ${text[1]}${text[2] ? ` (${text[2]})` : ''}`)
    } else {
      const label = { in: 'in', out: 'out', cache: 'cache', cost: 'cost' }[s.kind]
      parts.push(`${label} ${s.kind === 'cost' ? '$' : ''}${text[0]}`)
    }
  }
  return parts.length ? parts.join(' · ') : 'No usage yet: figures appear after the first model response.'
}

// ---------- hooks ----------

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'kullanim',
      description: 'Usage band: refresh and summarize (gizle hides, goster shows)',
    })
    $.clock.every(30_000, () => void refreshAll($).catch(() => undefined))
    void refreshAll($, true).catch(() => undefined)
    return next(e)
  })

  on('session.measure', async ($, e, next) => {
    await applyUsage($, e.rateLimits, e.cost?.usd ?? null, e.context)
    void refreshTokens($).catch(() => undefined)
    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    const u = e.usage
    if (u) {
      await update($, fallbackAtom, f => ({
        uncachedInput: f.uncachedInput + u.input_tokens,
        cacheWrite: f.cacheWrite + u.cache_creation_input_tokens,
        output: f.output + u.output_tokens,
        cacheRead: f.cacheRead + u.cache_read_input_tokens,
        turns: f.turns + 1,
      }))
    }
    void refreshTokens($).catch(() => undefined)
    return next(e)
  })

  on('command.run', { command: 'kullanim' }, async ($, e) => {
    const arg = e.args.trim().toLowerCase()
    if (arg === 'gizle') {
      await update($, hiddenAtom, () => true)
      return { text: 'Usage band hidden. /kullanim goster brings it back.' }
    }
    if (arg === 'goster' || arg === 'göster') {
      await update($, hiddenAtom, () => false)
      return { text: 'Usage band shown.' }
    }
    await refreshAll($, true)
    return { text: summary(await readModel($)) }
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey || (await read($, hiddenAtom))) return next(e)
    const m = await readModel($)
    if (specs(m).length === 0) return next(e)

    if (e.surface === 'terminal') {
      const { Box, Text } = $.ui.resolve(e)
      const groups: PillSpec[][] = [[], [], []]
      for (const s of specs(m)) groups[s.group]?.push(s)
      return (
        <Box flexDirection="row" flexWrap="wrap" columnGap={3}>
          {groups
            .filter(g => g.length > 0)
            .map((g, gi) => (
              <Box key={`g${gi}`} flexDirection="row" flexWrap="wrap" columnGap={2}>
                {g.map(s => (
                  <Text key={s.kind} color={TERM_COLOR[s.kind]}>
                    {s.parts.map((p, i) => {
                      const gap = i < s.parts.length - 1 ? ' ' : ''
                      if (p.t === 'icon') return `${TERM_ICON[p.name] ?? ''}${gap}`
                      if (p.t === 'sep') return `·${gap}`
                      if (p.t === 'text') {
                        return p.bold ? <Text bold>{p.s + gap}</Text> : p.s + gap
                      }
                      const b = termBar(p.pct, p.elapsed)
                      const cells = (b.fill + b.rest).split('')
                      return (
                        <Text color={LEVEL_COLOR[level(p.pct)]}>
                          {cells.map((c, ci) => (ci === b.mark ? '│' : c)).join('') + gap}
                        </Text>
                      )
                    })}
                  </Text>
                ))}
              </Box>
            ))}
        </Box>
      )
    }

    const els = $.ui.resolve(e)
    if (!('Svg' in els)) return next(e)
    const { Box, Svg } = els
    const pills = renderSvgPills(m)
    const groups = [0, 1, 2]
      .map(g => pills.filter(p => p.group === g))
      .filter(g => g.length > 0)
    return (
      <Box flexDirection="row" flexWrap="wrap" columnGap={3} rowGap={1}>
        {groups.map((g, gi) => (
          <Box key={`g${gi}`} flexDirection="row" flexWrap="wrap" columnGap={1}>
            {g.map(p => (
              <Svg key={p.kind} source={p.source} alt={p.alt} width={p.width} height={H} isInteractive />
            ))}
          </Box>
        ))}
      </Box>
    )
  })
}

