export type UsageWindow = { percentUsed: number; resetsAt: number | null }

export type UsageLimits = { fiveHour: UsageWindow | null; sevenDay: UsageWindow | null }

export type UsageContext = { tokens: number | null; window: number; percent: number | null }

export type UsageTokens = {
  uncachedInput: number
  cacheWrite: number
  output: number
  cacheRead: number
  requests: number
  isApprox: boolean
  dump: string
  subagentFiles: number
}

export type UsageFallback = {
  uncachedInput: number
  cacheWrite: number
  output: number
  cacheRead: number
  turns: number
}

declare module 'claude-code' {
  interface PluginState {
    'usage-band': {
      limits: UsageLimits | null
